import { test, expect } from '@playwright/test';

test.describe('User Profile - Display Name Update', () => {
  const testUser = {
    email: 'testuser@example.com',
    password: 'TestPassword123!',
    originalName: 'John Doe',
    newName: 'Jane Smith'
  };

  test.beforeEach(async ({ page }) => {
    // Navigate to the application
    await page.goto('/');

    // Login with test user
    await page.getByRole('link', { name: /sign in|login/i }).click();
    await page.getByLabel(/email/i).fill(testUser.email);
    await page.getByLabel(/password/i).fill(testUser.password);
    await page.getByRole('button', { name: /sign in|login/i }).click();

    // Wait for dashboard to load
    await page.waitForURL(/dashboard|home/);
  });

  test('should update display name in profile settings', async ({ page }) => {
    // Navigate to profile settings
    await page.getByRole('button', { name: /profile|account/i }).click();
    await page.getByRole('link', { name: /settings|profile settings/i }).click();

    // Wait for settings page to load
    await page.waitForURL(/settings|profile/);

    // Find and clear the display name field
    const displayNameField = page.getByLabel(/display name|full name/i);
    await displayNameField.clear();

    // Enter new display name
    await displayNameField.fill(testUser.newName);

    // Save changes
    await page.getByRole('button', { name: /save|update/i }).click();

    // Verify success message appears
    await expect(page.getByText(/successfully updated|changes saved/i)).toBeVisible();

    // Verify the display name field shows the new value
    await expect(displayNameField).toHaveValue(testUser.newName);
  });

  test('should reflect updated display name across the app', async ({ page }) => {
    // First, update the display name
    await page.getByRole('button', { name: /profile|account/i }).click();
    await page.getByRole('link', { name: /settings|profile settings/i }).click();

    const displayNameField = page.getByLabel(/display name|full name/i);
    await displayNameField.clear();
    await displayNameField.fill(testUser.newName);
    await page.getByRole('button', { name: /save|update/i }).click();

    // Wait for success message
    await expect(page.getByText(/successfully updated|changes saved/i)).toBeVisible();

    // Navigate to dashboard/home
    await page.getByRole('link', { name: /dashboard|home/i }).click();
    await page.waitForURL(/dashboard|home/);

    // Verify display name appears in header/navigation
    await expect(page.getByText(testUser.newName)).toBeVisible();

    // Navigate to user profile page
    await page.getByRole('button', { name: /profile|account/i }).click();
    await page.getByRole('link', { name: /view profile|my profile/i }).click();

    // Verify display name is shown on profile page
    await expect(page.getByRole('heading', { name: testUser.newName })).toBeVisible();
  });

  test('should validate display name field requirements', async ({ page }) => {
    // Navigate to profile settings
    await page.getByRole('button', { name: /profile|account/i }).click();
    await page.getByRole('link', { name: /settings|profile settings/i }).click();

    const displayNameField = page.getByLabel(/display name|full name/i);

    // Test empty display name
    await displayNameField.clear();
    await page.getByRole('button', { name: /save|update/i }).click();

    // Verify error message for empty field
    await expect(page.getByText(/required|cannot be empty|please enter/i)).toBeVisible();

    // Test with valid name
    await displayNameField.fill(testUser.newName);
    await page.getByRole('button', { name: /save|update/i }).click();

    // Verify success
    await expect(page.getByText(/successfully updated|changes saved/i)).toBeVisible();
  });

  test('should persist display name after page refresh', async ({ page }) => {
    // Update display name
    await page.getByRole('button', { name: /profile|account/i }).click();
    await page.getByRole('link', { name: /settings|profile settings/i }).click();

    const displayNameField = page.getByLabel(/display name|full name/i);
    await displayNameField.clear();
    await displayNameField.fill(testUser.newName);
    await page.getByRole('button', { name: /save|update/i }).click();

    // Wait for success message
    await expect(page.getByText(/successfully updated|changes saved/i)).toBeVisible();

    // Refresh the page
    await page.reload();

    // Verify display name is still updated
    await expect(displayNameField).toHaveValue(testUser.newName);
  });
});
